// 1. PELÍCULAS ORDENADAS POR NOMBREvoid listarPeliculasPorNombre() {    ArchivoPeliculas arc;    int cant = arc.contarRegistros();    if (cant <= 0) {        cout << "NO HAY PELICULAS REGISTRADAS." << endl;        return;    }    Pelicula *vec = new Pelicula[cant];    int contActivos = 0;    for (int i = 0; i < cant; i++) {        Pelicula obj = arc.leerRegistro(i);        if (obj.getEstado()) {            vec[contActivos] = obj;            contActivos++;        }    }    if (contActivos == 0) {        cout << "NO HAY PELICULAS ACTIVAS." << endl;        delete[] vec;        return;    }    for (int i = 0; i < contActivos - 1; i++) {        for (int j = 0; j < contActivos - i - 1; j++) {            if (strcmp(vec[j].getNombrePelicula(), vec[j+1].getNombrePelicula()) > 0) {                Pelicula aux = vec[j];                vec[j] = vec[j+1];                vec[j+1] = aux;            }        }    }    cout << "=== LISTADO DE PELICULAS (ORDENADAS POR NOMBRE) ===" << endl;    for (int i = 0; i < contActivos; i++) {        vec[i].Mostrar();        cout << "--------------------------------------------------" << endl;    }    delete[] vec;}// 2. GÉNEROS ORDENADOS POR NOMBREvoid listarGenerosPorNombre() {    ArchivoTipoGenero arc;    int cant = arc.contarRegistros();    if (cant <= 0) {        cout << "NO HAY GENEROS REGISTRADOS." << endl;        return;    }    TipoGenero *vec = new TipoGenero[cant];    int contActivos = 0;    for (int i = 0; i < cant; i++) {        TipoGenero obj = arc.leerRegistro(i);        if (obj.getEstado()) {            vec[contActivos] = obj;            contActivos++;        }    }    if (contActivos == 0) {        cout << "NO HAY GENEROS ACTIVOS." << endl;        delete[] vec;        return;    }    for (int i = 0; i < contActivos - 1; i++) {        for (int j = 0; j < contActivos - i - 1; j++) {            if (strcmp(vec[j].getNombreGenero(), vec[j+1].getNombreGenero()) > 0) {                TipoGenero aux = vec[j];                vec[j] = vec[j+1];                vec[j+1] = aux;            }        }    }    cout << "=== LISTADO DE GENEROS (ORDENADOS POR NOMBRE) ===" << endl;    for (int i = 0; i < contActivos; i++) {        vec[i].Mostrar();        cout << "--------------------------------------------------" << endl;    }    delete[] vec;}// 3. SALAS ORDENADAS POR NÚMERO DE SALAvoid listarSalasPorNumero() {    ArchivoSala arc;    int cant = arc.contarRegistros();    if (cant <= 0) {        cout << "NO HAY SALAS REGISTRADAS." << endl;        return;    }    Sala *vec = new Sala[cant];    int contActivos = 0;    for (int i = 0; i < cant; i++) {        Sala obj = arc.leerRegistro(i);        if (obj.getEstado()) {            vec[contActivos] = obj;            contActivos++;        }    }    if (contActivos == 0) {        cout << "NO HAY SALAS ACTIVAS." << endl;        delete[] vec;        return;    }    for (int i = 0; i < contActivos - 1; i++) {        for (int j = 0; j < contActivos - i - 1; j++) {            if (vec[j].getNumSala() > vec[j+1].getNumSala()) {                Sala aux = vec[j];                vec[j] = vec[j+1];                vec[j+1] = aux;            }        }    }    cout << "=== LISTADO DE SALAS (ORDENADAS POR NUMERO) ===" << endl;    for (int i = 0; i < contActivos; i++) {        vec[i].Mostrar();        cout << "--------------------------------------------------" << endl;    }    delete[] vec;}// 4. TIPOS DE SALA ORDENADOS POR DESCRIPCIÓNvoid listarTiposSalaPorDescripcion() {    ArchivoTipoSala arc;    int cant = arc.contarRegistros();    if (cant <= 0) {        cout << "NO HAY TIPOS DE SALA REGISTRADOS." << endl;        return;    }    TipoSala *vec = new TipoSala[cant];    int contActivos = 0;    for (int i = 0; i < cant; i++) {        TipoSala obj = arc.leerRegistro(i);        if (obj.getEstado()) {            vec[contActivos] = obj;            contActivos++;        }    }    if (contActivos == 0) {        cout << "NO HAY TIPOS DE SALA ACTIVOS." << endl;        delete[] vec;        return;    }    for (int i = 0; i < contActivos - 1; i++) {        for (int j = 0; j < contActivos - i - 1; j++) {            if (strcmp(vec[j].getDescSala(), vec[j+1].getDescSala()) > 0) {                TipoSala aux = vec[j];                vec[j] = vec[j+1];                vec[j+1] = aux;            }        }    }    cout << "=== LISTADO DE TIPOS DE SALA (ORDENADOS POR DESCRIPCIÓN) ===" << endl;    for (int i = 0; i < contActivos; i++) {        vec[i].Mostrar();        cout << "--------------------------------------------------" << endl;    }    delete[] vec;}// 5. FUNCIONES ORDENADAS POR PELÍCULA, FECHA Y HORAbool compararFunciones(Funcion a, Funcion b) {    if (a.getIdPelicula() != b.getIdPelicula()) {        return a.getIdPelicula() > b.getIdPelicula();    }    Fecha f1 = a.getFechaFuncion();    Fecha f2 = b.getFechaFuncion();    if (f1.getAnio() != f2.getAnio()) return f1.getAnio() > f2.getAnio();    if (f1.getMes() != f2.getMes()) return f1.getMes() > f2.getMes();    if (f1.getDia() != f2.getDia()) return f1.getDia() > f2.getDia();    return a.getHoraFuncion() > b.getHoraFuncion();}void listarFuncionesPorPeliculaYFecha() {    ArchivoFuncion arc;    int cant = arc.contarRegistros();    if (cant <= 0) {        cout << "NO HAY FUNCIONES REGISTRADAS." << endl;        return;    }    Funcion *vec = new Funcion[cant];    int contActivos = 0;    for (int i = 0; i < cant; i++) {        Funcion obj = arc.leerRegistro(i);        if (obj.getEstado()) {            vec[contActivos] = obj;            contActivos++;        }    }    if (contActivos == 0) {        cout << "NO HAY FUNCIONES ACTIVAS." << endl;        delete[] vec;        return;    }    for (int i = 0; i < contActivos - 1; i++) {        for (int j = 0; j < contActivos - i - 1; j++) {            if (compararFunciones(vec[j], vec[j+1])) {                Funcion aux = vec[j];                vec[j] = vec[j+1];                vec[j+1] = aux;            }        }    }    cout << "=== LISTADO DE FUNCIONES (POR PELICULA, FECHA Y HORA) ===" << endl;    for (int i = 0; i < contActivos; i++) {        vec[i].Mostrar();        cout << "--------------------------------------------------" << endl;    }    delete[] vec;}// 6. CLIENTES ORDENADOS POR DNIvoid listarClientesPorDNI() {    ArchivoCliente arc;    int cant = arc.contarRegistros();    if (cant <= 0) {        cout << "NO HAY CLIENTES REGISTRADOS." << endl;        return;    }    Cliente *vec = new Cliente[cant];    for (int i = 0; i < cant; i++) {        vec[i] = arc.leerRegistro(i);    }    for (int i = 0; i < cant - 1; i++) {        for (int j = 0; j < cant - i - 1; j++) {            if (vec[j].getDni() > vec[j+1].getDni()) {                Cliente aux = vec[j];                vec[j] = vec[j+1];                vec[j+1] = aux;            }        }    }    cout << "=== LISTADO DE CLIENTES (ORDENADOS POR DNI) ===" << endl;    for (int i = 0; i < cant; i++) {        vec[i].Mostrar();        cout << "--------------------------------------------------" << endl;    }    delete[] vec;}// 7. VENTAS ORDENADAS POR DNI DEL COMPRADORvoid listarVentasPorDNI() {    ArchivoVentaEntrada arc;    int cant = arc.contarRegistros();    if (cant <= 0) {        cout << "NO HAY VENTAS REGISTRADAS." << endl;        return;    }    VentaEntrada *vec = new VentaEntrada[cant];    for (int i = 0; i < cant; i++) {        vec[i] = arc.leerRegistro(i);    }    for (int i = 0; i < cant - 1; i++) {        for (int j = 0; j < cant - i - 1; j++) {            if (vec[j].getDniComprador() > vec[j+1].getDniComprador()) {                VentaEntrada aux = vec[j];                vec[j] = vec[j+1];                vec[j+1] = aux;            }        }    }    cout << "=== LISTADO DE VENTAS (ORDENADAS POR DNI COMPRADOR) ===" << endl;    for (int i = 0; i < cant; i++) {        vec[i].Mostrar();        cout << "--------------------------------------------------" << endl;    }    delete[] vec;}// 8. VENTAS ORDENADAS POR FUNCIÓN / PELÍCULAvoid listarVentasPorFuncion() {    ArchivoVentaEntrada arc;    int cant = arc.contarRegistros();    if (cant <= 0) {        cout << "NO HAY VENTAS REGISTRADAS." << endl;        return;    }    VentaEntrada *vec = new VentaEntrada[cant];    for (int i = 0; i < cant; i++) {        vec[i] = arc.leerRegistro(i);    }    for (int i = 0; i < cant - 1; i++) {        for (int j = 0; j < cant - i - 1; j++) {            if (vec[j].getIdFuncion() > vec[j+1].getIdFuncion()) {                VentaEntrada aux = vec[j];                vec[j] = vec[j+1];                vec[j+1] = aux;            }        }    }    cout << "=== LISTADO DE VENTAS (ORDENADAS POR FUNCION / PELICULA) ===" << endl;    for (int i = 0; i < cant; i++) {        vec[i].Mostrar();        cout << "--------------------------------------------------" << endl;    }    delete[] vec;}